export class ExpressEstimationError extends Error {
    constructor() {
        super(...arguments);
        this.name = "ExpressEstimationError";
    }
}
export class ExpressEstimationInsufficientGasPaymentTokenBalanceError extends ExpressEstimationError {
    constructor(params) {
        super();
        this.params = params;
        this.name = "ExpressEstimationInsufficientGasPaymentTokenBalanceError";
    }
}
export function getIsValidExpressParams({ gasPaymentValidations, }) {
    return gasPaymentValidations.isValid;
}
export function getIsConfirmedOutOfGasPaymentTokenBalance(gasPaymentValidations) {
    return Boolean(gasPaymentValidations?.isGasPaymentTokenBalanceLoaded && gasPaymentValidations.isOutGasTokenBalance);
}
